#include <bits/stdc++.h>
using namespace std;
bool can_sync(vector<int>&b){int n=b.size();vector<vector<char>> seen(n,vector<char>(n));queue<pair<int,int>>q;for(int i=0;i<n;i++){seen[i][i]=1;q.push({i,i});}vector<vector<vector<int>>> pre(2,vector<vector<int>>(n));for(int i=0;i<n;i++){pre[0][(i+1)%n].push_back(i);pre[1][b[i]].push_back(i);}while(!q.empty()){auto [u,v]=q.front();q.pop();for(int z=0;z<2;z++)for(int x:pre[z][u])for(int y:pre[z][v]){int a=min(x,y),c=max(x,y);if(!seen[a][c]){seen[a][c]=1;q.push({a,c});}}}for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(!seen[i][j])return false;return true;}
bool respects(vector<int>&b,int r){int n=b.size();vector<int>to(r,-1);vector<int>onto(r);for(int i=0;i<n;i++){int a=i%r,c=b[i]%r;if(to[a]!=-1 && to[a]!=c)return false;to[a]=c;}for(int j:to){if(onto[j]++)return false;}return true;}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):6;long long total=0,sync=0,classified=0,bad=0;vector<int>b(n);long long overlap[32]={};function<void(int)> dfs=[&](int i){if(i==n){int cnt[16]={};for(int v:b)cnt[v]++;int missing=0,doubleton=0;for(int j=0;j<n;j++){missing+=(cnt[j]==0);doubleton+=(cnt[j]==2);}if(missing!=1||doubleton!=1)return;total++;bool s=can_sync(b), c=0;int mask=0;for(int r=2;r<n;r++)if(n%r==0&&respects(b,r))mask|=1<<r,c=true;if(s)sync++;if(c)classified++;if(!s!=c){bad++;if(bad<6){cerr<<"mismatch b:";for(int a:b)cerr<<a;cerr<<" s "<<s<<" mask "<<mask<<endl;}}overlap[mask]++;return;}for(int j=0;j<n;j++){b[i]=j;dfs(i+1);}};dfs(0);cout<<"n "<<n<<" total "<<total<<" sync "<<sync<<" nonsync "<<total-sync<<" classified "<<classified<<" bad "<<bad<<endl;for(int i=0;i<32;i++)if(overlap[i])cout<<i<<":"<<overlap[i]<<" ";cout<<"\n"; if(n==4){if(total!=144||sync!=128||classified!=16||bad!=0)return 2;} if(n==8){if(total!=1128960||sync!=1114112||classified!=14848||bad!=0)return 2;} cout<<"CENSUS_VERIFY_OK"<<endl;}
